int restore_xstate(struct xsave_struct *fx, u64 mask) {
    int ret = 0;

    asm volatile(
        "1: xrstors %[fx], %[mask]\n"
        "2:\n"
        ".section .fixup,\"ax\"\n"
        "3: mov %[ret], 1\n"
        "   jmp 2b\n"
        ".previous\n"
        ".pushsection .note.GNU-stack, \"\", @progbits\n"
        ".popsection"
        : [fx] "+m"(*fx), [mask] "+rm"(mask)
        : "memory"
        : "cc", "rax", "rbx", "rcx", "rdx", "rax", "rbp", "rsi", "rdi", "r8",
          "r9", "r10", "r11", "r12", "r13", "r14", "r15"
        : "volatile"
    );

    return ret;
}

int restore_xstate(struct xsave_struct *fx, u64 mask) {
    int ret = 0;
    unsigned long flags;

    /* Check if xrstors is available and use it */
    if (boot_cpu_has(X86_FEATURE_XSAVES)) {
        asm volatile(
            "1: xrstors %0, %1\n"
            "2:\n"
            ".section .fixup,\"ax\"\n"
            "3: mov %3, %0\n"
            "   jmp 2b\n"
            ".previous\n"
            ".pushsection .note.GNU­­­x86.xfeature_use, \"ax@progbits\"\n"
            "   .octa 0\n"
            "   .octa 1\n"
            "   .octa 0\n"
            "   .octa 0\n"
            "   .octa %1\n"
            "   .octa 0\n"
            "   .octa 0\n"
            ".popsection\n"
            : : "m"(*fx), "r"(mask), "m"(ret), "i"(1) : "memory");
    } else {
        asm volatile("xrstor %0"
                     : : "m"(*fx),
                         "c"(mask));
    }

    return ret;
}

int restore_xsave_state(struct xsave_struct *fx, u64 mask) {
    int error = 0;

    if (supports_xrstors()) {
        __asm__ __volatile__(
            "xrstors %0, %1, %2\n"
            :
            : "m"(*fx), "n"(mask), "r"(error)
            : "memory");
    } else {
        __asm__ __volatile__(
            "xrstor %0, %1\n"
            :
            : "m"(*fx), "n"(mask)
            : "memory");
    }

    return error;
}

int restore_extended_state(struct xsave_struct *fx, u64 mask) {
    int err = 0;
    u64 xcr0;

    /* Read the xcr0 register to check feature availability */
    asm("xgetbv" : "=a"(xcr0) : "c"(0));

    if (xcr0 & (1ULL << 2)) {
        /* Use xrstors instruction if supported */
        asm volatile("xrstors %0, %1"
                     : 
                     : "m"(*fx), "r"(mask)
                     : "memory");
    } else {
        /* Fallback to xrstor if xrstors is not available */
        asm volatile("xrstor %0"
                     : 
                     : "m"(*fx));
    }

    return err;
}
